import { test } from "node:test";
import assert from "node:assert/strict";
import { encodeProveCall, encodeFinalizeCall, encodeFinalizeExternalCall, outputRootHash, withdrawalSlot, blockAtTimestamp, revertName } from "../src/prove.js";

// The reference encodings below were made with eth_abi 5.2.0, not with this code.
const TX = {
  nonce: 116402n,
  sender: "0x4200000000000000000000000000000000000007",
  target: "0x25ace71c97B33Cc4729CF772ae268934F7ab5fA1",
  value: 17980000000000000n,
  gasLimit: 1307593n,
  data: "0xd764ad0b" + "ab".repeat(37),
};
const ORP = { version: "0x" + "00".repeat(32), stateRoot: "0x" + "11".repeat(32), messagePasserStorageRoot: "0x" + "22".repeat(32), latestBlockhash: "0x" + "33".repeat(32) };
const PROOF = ["0xf90211" + "aa".repeat(30), "0xe2", "0x"];

const PROVE =
  "";
const FINALIZE =
  "";

test("proveWithdrawalTransaction is encoded exactly as eth_abi encodes it", () => {
  assert.equal(encodeProveCall(TX, 20883n, ORP, PROOF), PROVE);
});

test("finalizeWithdrawalTransaction is encoded exactly as eth_abi encodes it", () => {
  assert.equal(encodeFinalizeCall(TX), FINALIZE);
});

test("the output root is the hash of the four proof words, as Hashing.hashOutputRootProof computes it", () => {
  assert.equal(outputRootHash(ORP), "0xd50bf2ff34ced71be0d2f0be7c2433c6b39d9c3b16c95daf1ed6f24b7578a3b2");
});

test("the withdrawal's storage slot in L2ToL1MessagePasser is keccak(hash . 0)", () => {
  assert.equal(withdrawalSlot("0xd4b45b9d65cd6887388bc90334a922cf732554ec1acd0f244da2f873661ee3bc"), "0x7b7aac127c9171ce915c0a2e55e17f274772fa00755c3fcef84a2f3d112862a3");
});

test("the L2 block at a timestamp is counted back from the head at the chain's block time", () => {
  assert.equal(blockAtTimestamp({ number: 1000, timestamp: 5000 }, 4000, 2), 500);
  assert.equal(blockAtTimestamp({ number: 1000, timestamp: 5000 }, 5000, 2), 1000);
});

test("a revert from the portal is named by its error selector", () => {
  assert.equal(revertName("0x2e57ef3a"), "OptimismPortal_InvalidMerkleProof");
  assert.equal(revertName("0x12345678"), null);
});

test("finalizeWithdrawalTransactionExternalProof (anyone finalizes with another account's proof) matches eth_abi", () => {
  assert.equal(
    encodeFinalizeExternalCall(TX, "0x8fc7489af1fc446146b2a9a3ea6c91cf79ee12cc"),
    "",
  );
});
